import mongoose from 'mongoose';

/**
 * A registered device used by officials at a checkpoint. Device identity is
 * NOT a substitute for user authentication (plan §3.1) — it is bound to an
 * event and, through CheckpointSession, to an official and checkpoint.
 */
const raceDeviceSchema = new mongoose.Schema(
  {
    event: { type: mongoose.Schema.Types.ObjectId, ref: 'Event', required: true, index: true },
    label: { type: String, required: true, trim: true },

    // Stable UUID generated by the client at registration; used as the source
    // device identifier on every race event it records.
    deviceId: { type: String, required: true, unique: true, index: true },

    assignedOfficial: { type: mongoose.Schema.Types.ObjectId, ref: 'User' },
    defaultCheckpointType: { type: String, enum: ['start', 'lap', 'finish', 'any'], default: 'any' },

    active: { type: Boolean, default: true },
    lastSeenAt: { type: Date },
    lastSyncAt: { type: Date },
    lastReportedPending: { type: Number, default: 0 }, // last count the device reported (plan §12)

    createdBy: { type: mongoose.Schema.Types.ObjectId, ref: 'User' },
  },
  { timestamps: true }
);

export default mongoose.models.RaceDevice || mongoose.model('RaceDevice', raceDeviceSchema);
